window.POETRY_REGISTER("v5-strict-10-11-0-d510f5e789f8.js",{"poems":[[9971,2],[55554,2],[57581,2],[57946,2],[136368,7],[137680,7],[191197,7],[192125,7],[192130,7],[224366,7],[233390,7],[233445,7],[236005,7],[254622,7],[254623,7],[254624,7],[254625,7],[272346,7],[274382,7],[293917,7],[337800,9],[347193,9],[411268,8],[420547,8],[422431,8],[452924,8],[453910,8],[467896,8],[471420,8],[519324,8],[564128,8],[571800,8],[614596,8],[646993,15],[648431,16],[650074,5],[725696,5],[739676,20]],"pairs":[["若使巢由桎梏于轩冕兮","亦奚异乎夔龙蹩躠于风尘",0],["作者为死者王容之仲父","午咸通即咸通三年壬午岁",1],["今姑录存于杜光庭名下","祈读者引用时有以注意之",2],["北地的地名也时有所见","如前面提及的晋岭汾川等",3],["欲留君以陈遵投辖之饮","不如送君以陶令无弦之琴",4],["居于颓垣坏屋偪仄之巷","而有倜傥慷慨汪洋之美质",5],["庞居士悟心于马驹言下","裴相国得大用于黄蘗棒头",6],["吾有少陵之镵兮莠必耨","吾有尉佗之器兮蠹将奚逃",7],["公有豫章楩楠兮耸万仞","公有瑊玏玄厉兮磨而不磷",8],["又不见徂徕之山十丈雪","但见磊块硉兀错立于其中",9],["君不见晋朝失国隳金墉","为奴为胔岂惟怀愍巡北戎",10],["观吾生兮何为乎今之世","永悲伤兮耿耿夜长而鲜寐",11],["想丹旐兮埋圭玉于土中","千里泫然兮余独感此悲风",12],["昔之隠于此地兮将何求","后世之人兮因筑亭以遨游",13],["昔之隠于此地兮应甚安","后世之人兮因名亭以考槃",14],["昔之隠于此地兮信无患","后世之人兮因登亭以萧散",15],["昔之隠于此地兮自无怨","后世之人兮因兹亭以缱绻",16],["我不能舍我灵龟观朶颐","炊烟不动睡味恰与破衲宜",17],["如今红紫乱朱纷然而出","岂止乎少林五叶一花之春",18],["诸人睡眼豁开见得分晓","不起于座即超于然灯之前",19],["展花笺欲写几句知心事","空教我停霜毫半晌无才思",20],["二百年冠冕黼黻亦已极","犹有存者弘璧琰琬琳琅球",21],["君不见金华文章石室史","嗟我欲赋岂有笔力回千钧",22],["彼方以跖蹻之为洁廉兮","又奚慕乎夷齐采薇于首阳",23],["蓬莱蓬莱微茫不可以度","嗟我民昔捐瘠兮孰遗以哺",24],["君不见召南茇舍终烟草","惟有甘棠一曲千古被弦歌",25],["上则盘冈曲丘龙蛇虎蹲","其下膏场绣浍晻暧而渟洄",26],["我不能一麻一米骨作柴","亦不能啖硫黄钟乳十二钗",27],["君不见须眉文夫尽楚楚","胡为偷生反面视此曾无难",28],["茏茸晻霭不可以径度兮","但见烛龙向晓照耀从天来",29],["君不见竹林之下高韵长","高阳徒侣当年亦复气锵锵",30],["君不见钟山龙蟠虎踞雄","惟有江水万古与之无终穷",31],["我不能一麻一米骨作柴","亦不能啖硫黄钟乳十二钗",32],["安必其下在渊而上在天","中在五老之峰兮大月之山",33],["生倏忽兮如白驹之过隙","然不得欢乐兮当我之盛年",34],["庖牺氏人首蛇身古而怪","鼓弄着百姓结网打净了湾",35],["那知道异人返国着了道","又被个姓吕的光棍顶了包",35],["这是个白丁起手新兴样","把一个自古山河被他生掏",35],["十二道金牌害了岳武穆","那讲和的秦桧他不打死蛇",35],["真天子生来不是和尚料","出庙门便有些英雄入网罗",35],["不光是徐常沐邓称猛将","早有个军师刘基赛过萧何",35],["君不见盘旋屈曲如游龙","当空一落奇势飞动多横纵",36],["君不见子幼自劳羔日烹","何如命驾季鹰吴中煮莼羹",37],["又不见姜侯设鲙凿冰裂","何如徒步拾遗长镵黄独雪",37]]});
